qualifying_albums = []
for album in all_albums:
    album_song_ids = album['song_ids']
    if all(sid in downloaded_ids for sid in album_song_ids):
        # compute total duration
        total_duration = sum(song['duration'] for song in all_downloaded if song['song_id'] in album_song_ids)
        if total_duration >= 900:
            qualifying_albums.append((album['album_id'], album['title'], total_duration))

print("Qualifying albums (fully downloaded, >=15 min):")
for aid, title, dur in qualifying_albums:
    print(f"Album {aid}: {title} - {dur} seconds")

# Choose the one with the longest duration to maximize coverage
if qualifying_albums:
    best = max(qualifying_albums, key=lambda x: x[2])
    chosen_album_id = best[0]
    print(f"\nChosen album ID: {chosen_album_id}")
else:
    print("No qualifying album found")

